package com.example.finance.presentation;

import android.Manifest;
import android.app.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.activity.ComponentActivity;
import androidx.lifecycle.ViewModelProvider;
import androidx.core.content.ContextCompat;
import androidx.work.*;
import com.example.finance.data.*;
import com.example.finance.data.Operation;
import com.example.finance.domain.BudgetCalculator;
import com.example.finance.notification.ReminderWorker;
import java.text.NumberFormat;
import java.util.*;
import java.util.concurrent.TimeUnit;

public class MainActivity extends ComponentActivity {
 private FinanceViewModel vm; private LinearLayout body; private List<Account> accounts=new ArrayList<>(); private List<CategoryDetails> categories=new ArrayList<>();
 @Override public void onCreate(Bundle state){super.onCreate(state); vm=new ViewModelProvider(this).get(FinanceViewModel.class); showHome(); vm.accounts.observe(this,a->{accounts=a; render();}); vm.categories.observe(this,c->{categories=c;render();}); if(Build.VERSION.SDK_INT>=33 && ContextCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED) requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},1);}
 private TextView text(String s,int size){TextView v=FinanceStyle.label(this,s,size,FinanceStyle.INK,size>=18);v.setPadding(0,FinanceStyle.dp(this,6),0,FinanceStyle.dp(this,6));return v;}
 private void showHome(){
  getWindow().setStatusBarColor(FinanceStyle.BACKGROUND);getWindow().setNavigationBarColor(FinanceStyle.BACKGROUND);
  getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(FinanceStyle.BACKGROUND);setContentView(scroll);
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);int pad=FinanceStyle.dp(this,20);root.setPadding(pad,pad,pad,FinanceStyle.dp(this,28));scroll.addView(root);
  TextView heading=FinanceStyle.label(this,"Личные финансы",27,FinanceStyle.INK,true);root.addView(heading);
  java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("LLLL yyyy",new Locale("ru","RU"));TextView subtitle=FinanceStyle.label(this,fmt.format(new Date()),14,FinanceStyle.MUTED,false);root.addView(subtitle);FinanceStyle.addSpace(root,20);
  body=new LinearLayout(this);body.setOrientation(1);root.addView(body);render();
 }
 private void button(LinearLayout parent,String title,Runnable action){TextView b=FinanceStyle.action(this,title,false,action);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=FinanceStyle.dp(this,8);parent.addView(b,lp);}
 private void actionRow(LinearLayout parent,String left,Runnable l,String right,Runnable r){LinearLayout row=new LinearLayout(this);row.setOrientation(0);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.rightMargin=FinanceStyle.dp(this,8);row.addView(FinanceStyle.action(this,left,false,l),lp);row.addView(FinanceStyle.action(this,right,false,r),new LinearLayout.LayoutParams(0,-2,1));FinanceStyle.addCard(parent,row);}
 private void render(){
  if(body==null)return;body.removeAllViews();Calendar cal=Calendar.getInstance();cal.set(Calendar.DAY_OF_MONTH,1);cal.set(Calendar.HOUR_OF_DAY,0);cal.set(Calendar.MINUTE,0);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);long month=cal.getTimeInMillis();long total=0;
  for(CategoryDetails d:categories)for(Operation o:d.operations)if(o.createdAt>=month&&o.createdAt<=System.currentTimeMillis())total+=o.amount;
  LinearLayout summary=FinanceStyle.column(this,FinanceStyle.PALE_BLUE,20);summary.addView(FinanceStyle.label(this,"Расходы за месяц",14,0xFF365B69,false));FinanceStyle.addSpace(summary,8);summary.addView(FinanceStyle.label(this,money(total),30,0xFF001F2B,true));FinanceStyle.addSpace(summary,8);summary.addView(FinanceStyle.label(this,"Следите за расходами и лимитами",14,0xFF365B69,false));FinanceStyle.addCard(body,summary);
  FinanceStyle.addSpace(body,6);FinanceStyle.addCard(body,FinanceStyle.action(this,"+  Добавить расход",true,this::addExpense));actionRow(body,"+ Счёт",()->nameDialog(true),"+ Категория",()->nameDialog(false));
  FinanceStyle.addCard(body,FinanceStyle.action(this,"◷  Напоминание о платеже",false,this::reminderDialog));FinanceStyle.addSpace(body,12);
  body.addView(text("Мои счета и карты",20));FinanceStyle.addSpace(body,4);
  if(accounts.isEmpty()){LinearLayout empty=FinanceStyle.column(this,FinanceStyle.WHITE,18);empty.addView(FinanceStyle.label(this,"Пока нет счетов",16,FinanceStyle.INK,true));FinanceStyle.addSpace(empty,5);empty.addView(FinanceStyle.label(this,"Добавьте счёт, чтобы записывать расходы.",14,FinanceStyle.MUTED,false));FinanceStyle.addCard(body,empty);}
  for(Account a:accounts){LinearLayout card=FinanceStyle.column(this,0xFFE4EEF1,18);card.addView(FinanceStyle.label(this,"▣   СЧЁТ",12,FinanceStyle.PRIMARY,true));FinanceStyle.addSpace(card,10);card.addView(FinanceStyle.label(this,a.name,18,FinanceStyle.INK,true));FinanceStyle.addSpace(card,4);card.addView(FinanceStyle.label(this,"Нажмите для управления  ›",13,FinanceStyle.MUTED,false));card.setOnClickListener(v->accountActions(a));FinanceStyle.addCard(body,card);}
  FinanceStyle.addSpace(body,12);body.addView(text("Категории и лимиты",20));FinanceStyle.addSpace(body,4);
  if(categories.isEmpty()){LinearLayout empty=FinanceStyle.column(this,FinanceStyle.WHITE,18);empty.addView(FinanceStyle.label(this,"Начните с категории",16,FinanceStyle.INK,true));FinanceStyle.addSpace(empty,5);empty.addView(FinanceStyle.label(this,"Добавьте категорию и установите месячный лимит.",14,FinanceStyle.MUTED,false));FinanceStyle.addCard(body,empty);}
  for(CategoryDetails d:categories){long spent=0;for(Operation o:d.operations)if(o.createdAt>=month&&o.createdAt<=System.currentTimeMillis())spent+=o.amount;Budget b=d.budgets.isEmpty()?null:d.budgets.get(0);BudgetCalculator.Level level=BudgetCalculator.level(spent,b==null?0:b.amount,b==null?80:b.warningPercent);
   int accent=level==BudgetCalculator.Level.EXCEEDED?0xFFB3261E:level==BudgetCalculator.Level.WARNING?0xFF9A5800:0xFF1B8754;String status=level==BudgetCalculator.Level.EXCEEDED?"●  Лимит превышен":level==BudgetCalculator.Level.WARNING?"▲  Приближение к лимиту":level==BudgetCalculator.Level.NONE?"○  Лимит не задан":"✓  В пределах лимита";
   LinearLayout card=FinanceStyle.column(this,FinanceStyle.WHITE,18);card.addView(FinanceStyle.label(this,d.category.name,18,FinanceStyle.INK,true));FinanceStyle.addSpace(card,8);card.addView(FinanceStyle.label(this,"Расход за месяц  ·  "+money(spent),15,FinanceStyle.MUTED,false));if(b!=null){FinanceStyle.addSpace(card,4);card.addView(FinanceStyle.label(this,"Остаток  ·  "+money(b.amount-spent),15,FinanceStyle.INK,true));}FinanceStyle.addSpace(card,10);card.addView(FinanceStyle.label(this,status,14,accent,true));FinanceStyle.addSpace(card,4);card.addView(FinanceStyle.label(this,"Подробнее  ›",13,FinanceStyle.PRIMARY,false));card.setOnClickListener(v->categoryDetails(d));FinanceStyle.addCard(body,card);
  }
 }
 private String money(long cents){return NumberFormat.getCurrencyInstance(new Locale("ru","RU")).format(cents/100.0);}
 private EditText input(String hint){EditText e=new EditText(this);e.setHint(hint);return e;}
 private void nameDialog(boolean account){EditText e=input("Название");new AlertDialog.Builder(this).setTitle(account?"Новый счёт":"Новая категория").setView(e).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{String n=e.getText().toString().trim();if(n.isEmpty()){toast("Введите название");return;}vm.repository.run(()->{if(account){Account a=new Account();a.name=n;vm.repository.dao.addAccount(a);}else{Category c=new Category();c.name=n;vm.repository.dao.addCategory(c);}});}).show();}
 private void accountActions(Account a){new AlertDialog.Builder(this).setTitle(a.name).setItems(new String[]{"Переименовать","Удалить счёт"},(d,i)->{if(i==0){EditText e=input("Название");e.setText(a.name);new AlertDialog.Builder(this).setTitle("Переименовать").setView(e).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(x,y)->{String s=e.getText().toString().trim();if(!s.isEmpty()){a.name=s;vm.repository.run(()->vm.repository.dao.updateAccount(a));}}).show();}else confirm("Удалить счёт и его операции?",()->vm.repository.run(()->vm.repository.dao.deleteAccount(a)));}).show();}
 private void categoryDetails(CategoryDetails d){LinearLayout box=new LinearLayout(this);box.setPadding(20,10,20,10);box.setOrientation(1);button(box,"Установить месячный лимит",()->limitDialog(d));button(box,"Переименовать",()->renameCategory(d.category));button(box,"Удалить категорию",()->confirm("Удалить категорию, лимит и все её операции?",()->vm.repository.run(()->vm.repository.dao.deleteCategory(d.category))));box.addView(text("Операции (нажмите для удаления)",18));for(Operation o:d.operations){TextView row=text(o.note+"  ·  "+money(o.amount),16);box.addView(row);row.setOnClickListener(v->confirm("Удалить операцию?",()->vm.repository.run(()->vm.repository.dao.deleteOperation(o))));}new AlertDialog.Builder(this).setTitle(d.category.name).setView(box).setPositiveButton("Закрыть",null).show();}
 private void renameCategory(Category c){EditText e=input("Название");e.setText(c.name);new AlertDialog.Builder(this).setTitle("Категория").setView(e).setPositiveButton("Сохранить",(d,w)->{String s=e.getText().toString().trim();if(!s.isEmpty()){c.name=s;vm.repository.run(()->vm.repository.dao.updateCategory(c));}}).setNegativeButton("Отмена",null).show();}
 private Long amount(EditText e){try{long n=new java.math.BigDecimal(e.getText().toString().replace(',','.')).movePointRight(2).longValueExact();if(n<=0)throw new Exception();return n;}catch(Exception ex){toast("Введите положительную сумму с точностью до копеек");return null;}}
 private void limitDialog(CategoryDetails d){EditText e=input("Лимит в рублях");e.setInputType(8194);new AlertDialog.Builder(this).setTitle("Месячный лимит · "+d.category.name).setView(e).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(x,y)->{Long n=amount(e);if(n==null)return;Budget b=d.budgets.isEmpty()?new Budget():d.budgets.get(0);b.categoryId=d.category.id;b.amount=n;vm.repository.run(()->vm.repository.dao.putBudget(b));}).show();}
 private void addExpense(){if(accounts.isEmpty()||categories.isEmpty()){toast("Сначала добавьте счёт и категорию");return;}LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(20,0,20,0);Spinner as=new Spinner(this),cs=new Spinner(this);List<Account> aa=new ArrayList<>(accounts);List<CategoryDetails> cc=new ArrayList<>(categories);List<String> an=new ArrayList<>(),cn=new ArrayList<>();for(Account a:aa)an.add(a.name);for(CategoryDetails c:cc)cn.add(c.category.name);as.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,an));cs.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,cn));EditText sum=input("Сумма в рублях"),note=input("Описание");sum.setInputType(8194);box.addView(as);box.addView(cs);box.addView(sum);box.addView(note);new AlertDialog.Builder(this).setTitle("Новый расход").setView(box).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{Long n=amount(sum);if(n==null)return;Operation o=new Operation();o.accountId=aa.get(as.getSelectedItemPosition()).id;CategoryDetails c=cc.get(cs.getSelectedItemPosition());o.categoryId=c.category.id;o.amount=n;o.note=note.getText().toString().trim();o.createdAt=System.currentTimeMillis();vm.repository.run(()->vm.repository.dao.addOperation(o));if(!c.budgets.isEmpty()){Calendar cal=Calendar.getInstance();cal.set(Calendar.DAY_OF_MONTH,1);cal.set(Calendar.HOUR_OF_DAY,0);cal.set(Calendar.MINUTE,0);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);long total=n;for(Operation old:c.operations)if(old.createdAt>=cal.getTimeInMillis())total+=old.amount;Budget b=c.budgets.get(0);BudgetCalculator.Level l=BudgetCalculator.level(total,b.amount,b.warningPercent);if(l==BudgetCalculator.Level.WARNING||l==BudgetCalculator.Level.EXCEEDED)schedule("limit-"+c.category.id,"Лимит: "+c.category.name,l==BudgetCalculator.Level.EXCEEDED?"Лимит превышен":"Расходы приближаются к лимиту",0,false);}}).show();}
 private void reminderDialog(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(20,0,20,0);EditText name=input("Название платежа"),minutes=input("Через сколько минут напомнить");minutes.setInputType(2);box.addView(name);box.addView(minutes);CheckBox monthly=new CheckBox(this);monthly.setText("Повторять каждые 30 дней");box.addView(monthly);new AlertDialog.Builder(this).setTitle("Напоминание о платеже").setView(box).setNegativeButton("Отмена",null).setPositiveButton("Запланировать",(d,w)->{try{String s=name.getText().toString().trim();long m=Long.parseLong(minutes.getText().toString());if(s.isEmpty()||m<1||m>525600)throw new Exception();schedule("payment-"+UUID.randomUUID(),"Регулярный платёж",s,m,monthly.isChecked());toast("Напоминание запланировано");}catch(Exception e){toast("Укажите название и время от 1 до 525600 минут");}}).show();}
 private void schedule(String key,String title,String content,long delay,boolean repeat){Data data=new Data.Builder().putInt("id",key.hashCode()).putString("title",title).putString("text",content).build();WorkManager wm=WorkManager.getInstance(this);if(repeat){PeriodicWorkRequest r=new PeriodicWorkRequest.Builder(ReminderWorker.class,30,TimeUnit.DAYS).setInitialDelay(delay,TimeUnit.MINUTES).setInputData(data).build();wm.enqueueUniquePeriodicWork(key,ExistingPeriodicWorkPolicy.UPDATE,r);}else{OneTimeWorkRequest r=new OneTimeWorkRequest.Builder(ReminderWorker.class).setInitialDelay(delay,TimeUnit.MINUTES).setInputData(data).build();wm.enqueueUniqueWork(key,ExistingWorkPolicy.REPLACE,r);}}
 private void confirm(String msg,Runnable action){new AlertDialog.Builder(this).setMessage(msg).setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->action.run()).show();}private void toast(String msg){Toast.makeText(this,msg,Toast.LENGTH_LONG).show();}
}
